#!/usr/bin/env python3\n\"\"\"\nSimple Image Processor - واجهة سهلة لمعالجة الصور\nاكتب اسم الصورة وسيتم معالجتها تلقائياً\n\"\"\"\n\nfrom PIL import Image, ImageEnhance, ImageFilter\nimport os\nfrom pathlib import Path\n\n\ndef process_image():\n    print(\"=\"*50)\n    print(\"  مرحباً في برنامج معالجة الصور البسيط\")\n    print(\"=\"*50)\n    print()\n    \n    # اطلب من المستخدم اسم الصورة\n    image_name = input(\"أدخل اسم الصورة (مثال: image.jpg): \").strip()\n    \n    # تحقق من وجود الصورة\n    if not os.path.exists(image_name):\n        print(f\"❌ الصورة '{image_name}' غير موجودة!\")\n        return\n    \n    try:\n        # افتح الصورة\n        img = Image.open(image_name)\n        print(f\"✅ تم فتح الصورة بنجاح: {image_name}\")\n        print(f\"   الحجم الأصلي: {img.size}\")\n        print()\n        \n        # اعرض الخيارات\n        print(\"اختر العملية المطلوبة:\")\n        print(\"1. تحويل إلى رمادي (Grayscale)\")\n        print(\"2. تقليل الحجم (Resize)\")\n        print(\"3. زيادة السطوع (Brightness)\")\n        print(\"4. تطبيق ضبابية (Blur)\")\n        print(\"5. تحديد الحواف (Sharpen)\")\n        print(\"6. تطبيق جميع العمليات\")\n        print()\n        \n        choice = input(\"أدخل رقم الخيار (1-6): \").strip()\n        \n        # تطبيق العمليات\n        if choice == \"1\":\n            img = img.convert('L')\n            output_name = \"processed_grayscale.jpg\"\n            print(\"✅ تم التحويل إلى رمادي\")\n            \n        elif choice == \"2\":\n            width = int(input(\"أدخل العرض الجديد (بكسل): \"))\n            height = int(input(\"أدخل الارتفاع الجديد (بكسل): \"))\n            img = img.resize((width, height), Image.Resampling.LANCZOS)\n            output_name = f\"processed_resize_{width}x{height}.jpg\"\n            print(f\"✅ تم تقليل الحجم إلى {width}x{height}\")\n            \n        elif choice == \"3\":\n            factor = float(input(\"أدخل معامل السطوع (1.0 = عادي، أكبر = أفتح): \"))\n            enhancer = ImageEnhance.Brightness(img)\n            img = enhancer.enhance(factor)\n            output_name = \"processed_brightness.jpg\"\n            print(f\"✅ تم زيادة السطوع بمعامل {factor}\")\n            \n        elif choice == \"4\":\n            radius = float(input(\"أدخل قيمة الضبابية (0.5-5): \"))\n            img = img.filter(ImageFilter.GaussianBlur(radius=radius))\n            output_name = \"processed_blur.jpg\"\n            print(f\"✅ تم تطبيق الضبابية بقيمة {radius}\")\n            \n        elif choice == \"5\":\n            img = img.filter(ImageFilter.SHARPEN)\n            output_name = \"processed_sharpen.jpg\"\n            print(\"✅ تم تحديد الحواف\")\n            \n        elif choice == \"6\":\n            img = img.convert('L').convert('RGB')\n            enhancer = ImageEnhance.Brightness(img)\n            img = enhancer.enhance(1.2)\n            img = img.filter(ImageFilter.GaussianBlur(radius=1.5))\n            img = img.filter(ImageFilter.SHARPEN)\n            output_name = \"processed_all.jpg\"\n            print(\"✅ تم تطبيق جميع العمليات\")\n        else:\n            print(\"❌ اختيار غير صحيح!\")\n            return\n        \n        # احفظ الصورة\n        img.save(output_name)\n        print(f\"\\n💾 تم حفظ الصورة: {output_name}\")\n        print(f\"   الحجم الجديد: {img.size}\")\n        print(\"\\n✨ تمت العملية بنجاح!\")\n        \n    except Exception as e:\n        print(f\"❌ حدث خطأ: {str(e)}\")\n\n\nif __name__ == \"__main__\":\n    process_image()\n